const dzis = new Date();
console.log(dzis.getMonth());
// wynik 0-11: 0 to styczen, 8 to wrzesien, 11 to grudzien -
// miesiac jest INDEKSOWANY OD ZERA, dokladnie jak indeksy tablic

const dzis = new Date();
console.log(dzis.getDate()); // np. 16 (dzien miesiaca)
console.log(dzis.getDay());  // np. 3 (dzien tygodnia, 0=niedziela)

const data = new Date(2025, 4, 1);
console.log(data.getFullYear(), data.getMonth(), data.getDate());
// 2025 4 1

const wigilia = new Date("2025-12-24T18:00:00");
console.log(wigilia.getFullYear()); // 2025
console.log(wigilia.getDate());     // 24

const start = new Date(2025, 0, 1);
const koniec = new Date(2025, 0, 20);

const roznicaMs = koniec.getTime() - start.getTime();
const dni = roznicaMs / (1000 * 60 * 60 * 24);
console.log(dni); // 19

const urodziny = new Date(1995, 2, 15);
const wiek = new Date().getFullYear() - urodziny.getFullYear();
console.log(wiek); // np. 31 (zalezne od biezacego roku)

const nazwyMiesiecy = ["Styczen", "Luty", "Marzec", "Kwiecien", "Maj", "Czerwiec", "Lipiec", "Sierpien", "Wrzesien", "Pazdziernik", "Listopad", "Grudzien"];
const data = new Date(2025, 5, 1);
console.log(nazwyMiesiecy[data.getMonth()]); // "Czerwiec"

const nazwyMiesiecy = ["Styczen", "Luty", "Marzec", "Kwiecien", "Maj", "Czerwiec"];
const data = new Date(2025, 5, 1); // czerwiec
console.log(nazwyMiesiecy[data.getMonth() - 1]); // "Maj" - BLEDNIE, powinno byc "Czerwiec"

const dataStart = new Date(2025, 0, 1);
const dataKoniec = new Date(2025, 11, 31);

const roznicaDni = (dataKoniec.getTime() - dataStart.getTime()) / (1000 * 60 * 60 * 24);
const tygodnie = Math.floor(roznicaDni / 7);
console.log(tygodnie); // 52

function czyPelnoletni(dataUrodzenia) {
  return new Date().getFullYear() - dataUrodzenia.getFullYear() >= 18;
}

const terazRok = new Date().getFullYear();
console.log(czyPelnoletni(new Date(terazRok - 20, 0, 1))); // true
console.log(czyPelnoletni(new Date(terazRok - 10, 0, 1))); // false

const data = new Date(2025, 5, 15);
const dzienTygodnia = data.getDay();
const jestWeekend = dzienTygodnia === 0 || dzienTygodnia === 6;
console.log(jestWeekend); // zalezy od konkretnego dnia tygodnia 15 czerwca 2025

const daty = [new Date(2025, 0, 1), new Date(2025, 5, 1), new Date(2025, 11, 1)];
const miesiace = daty.map(d => d.getMonth());
console.log(miesiace); // [0, 5, 11]

function dniDoDeadline(deadline) {
  const teraz = new Date();
  const roznicaMs = deadline.getTime() - teraz.getTime();
  return Math.ceil(roznicaMs / (1000 * 60 * 60 * 24));
}

const za10Dni = new Date(Date.now() + 10 * 24 * 60 * 60 * 1000);
console.log(dniDoDeadline(za10Dni)); // 10 (moze byc 9 lub 10 w zaleznosci od dokladnej godziny)

const data1 = new Date(2025, 0, 1);
const data2 = new Date(2025, 0, 1);

console.log(data1 === data2);               // false - rozne obiekty
console.log(data1.getTime() === data2.getTime()); // true - ten sam moment w czasie

function formatujDate(data) {
  const dzien = String(data.getDate()).padStart(2, "0");
  const miesiac = String(data.getMonth() + 1).padStart(2, "0");
  const rok = data.getFullYear();
  return `${dzien}.${miesiac}.${rok}`;
}

console.log(formatujDate(new Date(2025, 2, 5))); // "05.03.2025"

const czas1 = Date.now();
const czas2 = new Date().getTime();
console.log(Math.abs(czas1 - czas2) < 100); // true - roznica to najwyzej kilka milisekund

const urodzeni = [new Date(1990, 5, 1), new Date(1985, 2, 15), new Date(2000, 8, 20)];
const posortowani = [...urodzeni].sort((a, b) => a.getTime() - b.getTime());

console.log(posortowani.map(d => d.getFullYear())); // [1985, 1990, 2000]

function jestPrzeszlaData(data) {
  return data.getTime() < Date.now();
}

console.log(jestPrzeszlaData(new Date(2020, 0, 1))); // true
console.log(jestPrzeszlaData(new Date(2099, 0, 1))); // false

const event = { nazwa: "Konferencja", data: new Date(2025, 8, 15) };
const json = JSON.stringify(event);
const sparsowany = JSON.parse(json);

console.log(typeof sparsowany.data); // "string" - Date stal sie zwyklym stringiem

function pierwszyDzienMiesiaca(rok, miesiac) {
  return new Date(rok, miesiac, 1);
}

const pierwszyMarca = pierwszyDzienMiesiaca(2025, 2);
console.log(pierwszyMarca.getDate(), pierwszyMarca.getMonth()); // 1 2

function ostatniDzienMiesiaca(rok, miesiac) {
  return new Date(rok, miesiac + 1, 0).getDate();
}

console.log(ostatniDzienMiesiaca(2024, 1)); // 29 - luty 2024 to rok przestepny

const rano = new Date(2025, 5, 15, 8, 0);
const wieczorem = new Date(2025, 5, 15, 20, 0);

console.log(rano.getDate() === wieczorem.getDate()); // true - ten sam dzien
console.log(rano.getTime() === wieczorem.getTime());  // false - rozna godzina

function dniTygodniaNazwa(data) {
  const dni = ["Niedziela", "Poniedzialek", "Wtorek", "Sroda", "Czwartek", "Piatek", "Sobota"];
  return dni[data.getDay()];
}

console.log(dniTygodniaNazwa(new Date(2025, 0, 1))); // "Sroda"

const wydarzenia = [{ nazwa: "A", data: new Date(2025, 5, 1) }, { nazwa: "B", data: new Date(2025, 2, 1) }];
const posortowane = [...wydarzenia].sort((a, b) => a.data.getTime() - b.data.getTime());

console.log(posortowane.map(w => w.nazwa)); // ['B', 'A']

